import std.signal.*
import std.math.*

i32 main() {
    // Generate a sine wave
    let n: i32 = 64;
    let mut signal: f64[64];
    for (i32 i = 0; i < n; i++) {
        let t = f64(i) / f64(n);
        signal[i] = sin(2.0 * 3.14159 * 4.0 * t) + 0.5 * sin(2.0 * 3.14159 * 12.0 * t);
    }

    println("Generated composite signal (4Hz + 12Hz)");
    println("Running DFT...");

    let mut spectrum: f64[64];
    dft(signal, spectrum, n);

    println("Frequency spectrum (first 32 bins):");
    for (i32 i = 0; i < 32; i++) {
        let bar: str = "";
        let val = i32(f64(spectrum[i] * 20.0));
        for (i32 j = 0; j < val && j < 40; j++) {
            bar = bar + "#";
        }
        println(i32_to_str(i) + ": " + f64_to_str(spectrum[i]) + " " + bar);
    }

    return 0;
}

i32 dft(f64[] input, f64[] output, i32 n) {
    for (i32 k = 0; k < n / 2; k++) {
        let mut real: f64 = 0.0;
        let mut imag: f64 = 0.0;
        for (i32 t = 0; t < n; t++) {
            let angle = 2.0 * 3.14159 * f64(k) * f64(t) / f64(n);
            real = real + input[t] * cos(angle);
            imag = imag + input[t] * sin(angle);
        }
        output[k] = sqrt(real * real + imag * imag) / f64(n);
    }
    return 0;
}

import std.graphics.*
import std.linalg.*

i32 main() {
    // Initialize renderer
    let width: i32 = 800;
    let height: i32 = 600;
    let ctx = create_context(width, height, "Vex Playground");

    // Create a simple triangle mesh
    let verts: float3[3] = [
        float3(-0.5, -0.5, 0.0),
        float3(0.5, -0.5, 0.0),
        float3(0.0, 0.5, 0.0)
    ];

    let colors: float3[3] = [
        float3(1.0, 0.0, 0.0),
        float3(0.0, 1.0, 0.0),
        float3(0.0, 0.0, 1.0)
    ];

    // Set up camera
    let eye = float3(0.0, 0.0, 2.5);
    let target = float3(0.0, 0.0, 0.0);
    let up = float3(0.0, 1.0, 0.0);
    let view = look_at(eye, target, up);

    let fov: f64 = 60.0;
    let aspect = f64(width) / f64(height);
    let proj = perspective(fov, aspect, 0.1, 100.0);

    // Render loop (single frame)
    clear(ctx, float3(0.1, 0.1, 0.15));

    let model = identity4();
    let mvp = proj * view * model;

    draw_triangles(ctx, verts, colors, 1, mvp);

    // Output
    println("Rendered triangle to " + i32_to_str(width) + "x" + i32_to_str(height));
    println("Context: " + ptr_to_str(ctx));
    println("Vertices: 3, Colors: 3, Faces: 1");
    println("MVP matrix applied, camera at z=2.5");

    // Present
    present(ctx);
    destroy_context(ctx);

    return 0;
}
